import spock.lang.Stepwise
import spock.lang.Subject
import spock.lang.Unroll

import javax.persistence.EntityManager

@Stepwise
class OracleEbsSteps extends geb.bdd.SpockGebReportingSpec {

    @Subject
    def invoiceManagementService

    def entityManager

    def setup() {
        invoiceManagementService = context.getBean('invoiceManagementService')
        entityManager = context.getBean(EntityManager)
    }

    def cleanup() {
        entityManager.createQuery("DELETE FROM Invoice").executeUpdate()
    }

    @Unroll
    def 'create an invoice and verify in Oracle EBS' (String name, String address, String amount) {
        given: 'A valid invoice'
        def invoice = new Invoice(
                name: DataFaker.getName(),
                address: DataFaker.getAddress(),
                amount: new BigDecimal(amount)
        )

        when: 'I POST the invoice to Invoice Management RESTful API'
        def response = invoiceManagementService.createInvoice(invoice)

        then: 'The server returns a 201 response'
        response.statusCode == 201

        and: 'And the invoice exists in Oracle EBS'
        def ebsInvoices = entityManager.createQuery("SELECT i FROM Invoice i WHERE i.name = :name AND " +
                "i.address = :address AND i.amount = :amount").setParameter('name', invoice.name)
                .setParameter('address', invoice.address)
                .setParameter('amount', invoice.amount).getResultList()

        ebsInvoices.size() == 1

        where:
        name       | address     | amount
        'John Doe' | '123 Main St'| '100.00'
    }
}
```

