   - `type-defs.ts`: contenant les définitions des types de graphe GraphQL

8. Dans le fichier `resolvers.ts`, écrivez le code suivant :

```TypeScript
import { AfterLoad, Column, Entity, ManyToMany, ManyToOne, OneToMany, PrimaryGeneratedColumn } from 'typeorm';
import { Field, ID, ObjectType } from 'type-graphql';
import { Connection } from './Connection';
import { User } from './User';

@ObjectType()
@Entity()
export class Session {
  @Field(() => ID)
  @PrimaryGeneratedColumn()
  id: number;

  @Field()
  @Column({ nullable: false })
  token: string;

  @ManyToOne(() => User, (user) => user.sessions)
  user: User;

  @Field(() => [Connection])
  @OneToMany(() => Connection, (connection) => connection.sessionReceiver)
  connectionsReceiver: Connection[];

  @Field(() => [Connection])
  @OneToMany(() => Connection, (connection) => connection.sessionSender)
  connectionsSender: Connection[];

  @AfterLoad()
  async populateConnections() {
    this.connectionsReceiver = await getRepository(Connection).find({
      receiver: this.user,
      session: this,
    });

    this.connectionsSender = await getRepository(Connection).find({
      sender: this.user,
      session: this,
    });
  }
}
```

