    _: String
  }

  type Mutation {
    _: String
  }

  type User {
    id: ID! @id
    username: String! @field(resolve: () => 'user')
  }

  type Session {
    id: ID! @id
    token: String! @field(resolve: () => 'session')
    user: User! @field(resolve: (session) => session.user)
    connectionsReceiver: [Connection!]! @relation(name: 'receiver_session', joinTable: true)
    connectionsSender: [Connection!]! @relation(name: 'sender_session', joinTable: true)
  }

  type Connection {
    id: ID! @id
    callerId: String! @field(resolve: () => 'connection.callerId')
    receiverId: String! @field(resolve: () => 'connection.receiverId')
    caller: User! @field(resolve: (connection) => connection.caller)
    receiver: User! @field(resolve: (connection) => connection.receiver)
    session: Session! @field(resolve: () => 'connection.session')
  }
`;
```

