class IntQueue:
    def __init__(self):
        self.queue = {}
        self.count = 0

    def enqueue(self, element):
        self.queue[self.count] = element
        self.count += 1

    def dequeue(self):
        if self.count == 0:
            return None
        else:
            element = self.queue.pop(0)
            self.count -= 1
            return element

    def seeSaw(self):
        if self.count < 2:
            return None
        total = self.queue[0] + 1 / self.queue[1]
        count = 2
        current_index = 2
        while current_index < self.count:
            if count % 2 == 0:
                temp = self.queue[current_index]
            count += 1
            if count % 2 == 1:
