```
class FractionStack:
    def __init__(self):
        self.data = []  # liste contenant les paires (élément, fraction)

    def is_empty(self):
        return len(self.data) == 0

    def push(self, num):
        if isinstance(num, (int, float)):
            frac = 1  # fraction par défaut pour un entier
        elif isinstance(num, tuple) and len(num) == 2 and isinstance(num[0], (int, float)) and isinstance(num[1], (int, float)):
            num, frac = num
        else:
            raise TypeError("Le paramètre 'num' doit être un nombre entier, une fraction (tupple) ou ne pas être instanciable.")

        self.data.append((num, frac))

    def pop(self):
        if self.is_empty():
            raise IndexError("Stack is empty")
        return self.data.pop()[0]

    def seesaw(self):
        if self.is_empty():
            raise IndexError("Stack is empty")

        # Calculer la somme fractionnée:
        frac_sum = 0
        for I in range(0, len(self.data), 2):
            frac_sum += self.data[i][1] + self.data[i+1][1]

        # Retourner la somme simplifiée
        return self._simplify(frac_sum)

    def _simplify(self, frac_sum):
        # Simplifier la fraction en réduisant le dénominateur le plus possible en utilisant la fonction communatrice
        common_denominator = max(d[1] for d in self.data)  # Utiliser le dénominateur maximal des fractions actuellement stockées

        frac_sum *= common_denominator
        frac_sum = round(frac_sum)  # Tronquer la fraction par défaut

        return frac_sum // common_denominator

    def __len__(self):
        return len(self.data)
```

