module.exports = {
  extends: ['plugin:vue/recommended'],
  rules: {
    // Ajoutez une règle personnalisée pour vérifier le hook de vie de cycle
    'vue/component-modifiers-state-changes': {
      // définition de la règle
      enforce: 'error',
      message: 'Hook de cycle de vie mis à jour ne doit pas modifier l\'état du composant interne',
      meta: {
        fixable: true, // indique que la règle est corrigeable automatiquement
        docs: {
          description: 'Prevent updating lifecycle hooks from modifying the component instance state.',
          category: 'Best Practices',
          recommended: true,
        },
        schema: [
          {
            type: 'object',
            properties: {
              allowMethods: {
                type: 'array',
                items: { type: 'string' },
                default: [], // liste des méthodes qui sont autorisées à modifier l'état du composant
              },
              forbidMethods: {
                type: 'array',
                items: { type: 'string' },
                default: [
                  'setData', // rajoutez ici les noms de méthodes relatives à l'état du composant que vous souhaitez interdire de modifier
                ],
              },
            },
            additionalProperties: false,
          },
        ],
      },
      create: function(context) {
        return {
          // Vérifie les hooks de cycle de vie mis à jour
          'VoidMethodCall': function(node) {
            if (node.method && CUSTOM_LIFECYCLE_HOOKS.includes(node.method.name)) {
              const methodName = node.method.name;

              // Vérifie s'il s'agit d'un appel de méthode qui modifie l'état du composant interne
              const isStateChange = context.options[0]?.forbidMethods.some(forbiddenMethod =>
                methodName === forbiddenMethod || node.arguments.some(arg =>
                  arg.type.isMemberExpression() &&
                  arg.object.type.isThis() &&
                  arg.object.kinda === 'MemberExpression' &&
                  arg.object.property.name === 'data' &&
                  arg.type.isMemberExpression() &&
                  arg.object.type.isMemberExpression() &&
                  arg.object.object.type.isThis() &&
                  (arg.property.type === 'Identifier' && arg.property.name === forbiddenMethod)
                )
              );

              if (isStateChange) {
                // Vérifie si la méthode appelée ne doit pas être interdite
                if (
                  context.options[0]?.forbidMethods.includes(methodName) ||
                  context.options[0]?.allowMethods.includes(methodName)
                ) {
                  return;
                }

                context.report({
                  node,
                  message: context.options[0]?.message,
                  fix(fixer) {
                    const methodNameIndex = node.method.range()[0];

                    // Remplacez la méthode appelée avec la chaîne vide pour la supprimer
                    return fixer.removeRange([
                      methodNameIndex,
                      methodNameIndex + node.method.name.range()[1],
                    ]);
                  },
                });
              }
            }
          },
        };
      },
    },
  },
};
```

3. Remplacez `CUSTOM_LIFECYCLE_HOOKS` (ligne 23 dans le code ci-dessus) par une liste des noms des hooks de cycle de vie que vous souhaitez vérifier. Par exemple, pour vérifier les hooks `beforeCreate` et `beforeUpdate`, modifiez le code comme suit :

